/* * @lc app=leetcode id=1505 lang=kotlin * * [1505] Minimum Possible Integer After at Most K Adjacent Swaps On Digits */ class Solution { fun minInteger(num: String, k: Int): String = Array(10) { java.util.ArrayDeque<Int>() }.also { pos -> num.indices.forEach { pos[num[it] - '0'].add(it) } }.let { pos -> IntArray(num.length + 1).let { bit -> StringBuilder().also { sb -> (0 until num.length).fold(k) { rem, _ -> (0..9).first { d -> pos[d].peek()?.let { idx -> idx - generateSequence(idx + 1) { it - (it and -it) }.takeWhile { it > 0 }.sumOf { bit[it] } <= rem } ?: false }.let { d -> pos[d].poll()!!.let { idx -> idx - generateSequence(idx + 1) { it - (it and -it) }.takeWhile { it > 0 }.sumOf { bit[it] }.also { generateSequence(idx + 1) { it + (it and -it) }.takeWhile { it <= num.length }.forEach { bit[it] += 1 }.also { sb.append(d) } } }.let { cost -> rem - cost } } } }.toString() } } }